/* ============================================================
   TURQUESA HUB · ADMINISTRACIÓN DE LA FUNDACIÓN MILAGRO DE ABRIL
   Tablero, organizaciones (estados, autorizaciones, avances), instrumento
   y diagnósticos (alcance y versiones), planes, editorial de contenidos
   (flujo técnico → jurídico → psicosocial → aprobado → publicado, con
   revisiones registradas por la persona autorizada), formación,
   manifestaciones de interés en el Sello, reportes, usuarios y permisos,
   trazabilidad y configuración. Cada vista exige rol fma y, cuando aplica,
   el permiso indicado en la ruta.
   ============================================================ */
window.TH = window.TH || {};

(function () {
  const esc = (s) => TH.util.esc(s);
  const ic = (n, c) => TH.ui.icono(n, c);
  const cat = TH.data.catalogos; const instr = TH.data.instrumento;
  const ROLES = ['fma'];
  const ui = { orgQ: '', orgEstado: '', orgSector: '', contQ: '', contEstado: '', contCat: '', selEstado: '', audEntidad: '', audQ: '' };
  const puede = (p) => TH.auth.tienePermiso(p);
  const dimNombre = (id) => (instr.dimensiones.find(d => d.id === id) || {}).corto || id;
  const nombreUsuario = (id) => { if (id === 'sistema') return 'Sistema'; const u = TH.api.usuarios.obtener(id); return u ? u.nombre : id; };

  /* ================= TABLERO ================= */
  function inicio() {
    const t = TH.api.reportes.tableroFMA(); const prom = TH.api.reportes.dimensionesPromedio();
    const pendientesEditorial = TH.api.contenidos.listar().filter(c => ['en-revision-tecnica', 'en-revision-juridica', 'en-revision-psicosocial', 'aprobado'].includes(c.estado)).length;
    const u = TH.auth.usuario();
    return TH.ui.encabezado('Tablero general', 'Hola, ' + esc(u.nombre.split(' ')[0]) + '. Estado de la plataforma y de las organizaciones vinculadas.') +
      '<div class="grid grid-4">' + TH.ui.kpi('Organizaciones', String(t.organizaciones), t.activas + ' activas · ' + t.suspendidas + ' suspendidas', true) + TH.ui.kpi('Autodiagnósticos', String(t.diagnosticosTerminados), 'completados de ' + t.diagnosticosIniciados + ' iniciados') + TH.ui.kpi('Planes de acción', String(t.planes), t.accionesTotal + ' acciones · ' + t.accionesCompletadasPct + '% completadas') + TH.ui.kpi('Participantes', String(t.colaboradoresParticipantes), t.actividadesFormativas + ' módulos completados') + '</div>' +
      '<div class="grid grid-3 mt-4">' + TH.ui.kpi('Contenidos en revisión', String(pendientesEditorial), 'pendientes de revisión o publicación') + TH.ui.kpi('Interés en el Sello', String(t.interesesSello), t.interesesSinGestionar + ' sin gestionar') + TH.ui.kpi('Acciones atrasadas', String(t.accionesAtrasadas), 'en todos los planes') + '</div>' +
      '<div class="grid grid-2 mt-4"><div class="card"><h3 class="card__titulo">Lectura promedio por dimensión</h3><p class="card__sub mb-3">Valores orientativos declarados por las organizaciones con autodiagnóstico completo.</p>' + TH.graficos.barras(prom.map(p => ({ etiqueta: p.dim.corto + ' (n=' + p.n + ')', valor: p.promedio }))) + '</div>' +
      '<div class="card"><h3 class="card__titulo">Organizaciones por sector</h3>' + TH.graficos.barras(t.porSector.map(x => ({ etiqueta: x.etiqueta, valor: x.valor })), { max: Math.max(1, ...t.porSector.map(x => x.valor)), sufijo: '' }) + '</div></div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Actividad reciente</h3>' + TH.ui.historial(TH.api.historial.listar().slice(0, 8).map(h => ({ fecha: h.fecha, actor: nombreUsuario(h.actorId), accion: h.accion }))) + '<a class="btn btn--terciario btn--sm mt-2" href="#/fma/auditoria">Ver trazabilidad completa</a></div>';
  }

  /* ================= ORGANIZACIONES ================= */
  function organizaciones() {
    const lista = TH.api.organizaciones.listar({ q: ui.orgQ, estado: ui.orgEstado, sector: ui.orgSector });
    return TH.ui.encabezado('Organizaciones', 'Organizaciones registradas, estado de autorización y avance en la gestión preventiva.', '<button type="button" class="btn btn--secundario" data-action="fma-exportar-orgs">' + ic('descargar') + ' CSV</button>') +
      '<div class="filtros"><div class="buscador campo">' + ic('lupa') + '<label class="sr-only" for="oq">Buscar</label><input class="input" id="oq" type="search" placeholder="Nombre, NIT, municipio, responsable" value="' + esc(ui.orgQ) + '" data-input="fma-org-q"></div>' +
      '<div class="campo"><label class="sr-only" for="oe">Estado</label><select class="select" id="oe" data-change="fma-org-estado"><option value="">Todos los estados</option>' + cat.estadosOrganizacion.map(e => '<option value="' + e.id + '" ' + (ui.orgEstado === e.id ? 'selected' : '') + '>' + esc(e.nombre) + '</option>').join('') + '</select></div>' +
      '<div class="campo"><label class="sr-only" for="os">Sector</label><select class="select" id="os" data-change="fma-org-sector"><option value="">Todos los sectores</option>' + cat.sectores.map(s => '<option ' + (ui.orgSector === s ? 'selected' : '') + '>' + esc(s) + '</option>').join('') + '</select></div></div>' +
      TH.ui.tabla([
        { titulo: 'Organización', render: o => '<a href="#/fma/organizaciones/detalle?id=' + o.id + '"><strong>' + esc(o.nombre) + '</strong></a><div class="texto-xs texto-2">' + esc(o.tipoIdentificacion || '') + ' ' + esc(o.identificacion || '') + ' · ' + esc(o.municipio) + ', ' + esc(o.departamento) + '</div>' },
        { titulo: 'Sector / tamaño', render: o => esc(o.sector) + '<div class="texto-xs texto-2">' + esc(TH.util.nombreCatalogo(cat.tamanos, o.tamano)) + '</div>' },
        { titulo: 'Responsable', render: o => esc(o.responsable) + '<div class="texto-xs texto-2">' + esc(o.email) + '</div>' },
        { titulo: 'Registro', render: o => esc(TH.util.fecha(o.fechaRegistro)) },
        { titulo: 'Diagnóstico', render: o => { const r = TH.api.organizaciones.resumen(o.id); return r.diagnosticoEstado === 'completado' ? TH.ui.badge('Completado', 'exito') : r.diagnosticoEstado === 'en-curso' ? TH.ui.badge(r.diagnosticoPct + '%', 'info') : TH.ui.badge('No iniciado', 'neutro'); } },
        { titulo: 'Plan', render: o => { const r = TH.api.organizaciones.resumen(o.id); return r.plan ? TH.ui.progreso(r.planPct) : '<span class="texto-2">—</span>'; } },
        { titulo: 'Estado', render: o => TH.ui.badgeCatalogo(cat.estadosOrganizacion, o.estado) },
        { titulo: '', clase: 'acciones', render: o => '<a class="btn btn--terciario btn--sm" href="#/fma/organizaciones/detalle?id=' + o.id + '">Ver</a>' }
      ], lista, { caption: 'Organizaciones registradas', vacioTitulo: 'Sin organizaciones', vacioTexto: 'No hay organizaciones que coincidan con los filtros.' });
  }
  function organizacionDetalle(ctx) {
    const o = TH.api.organizaciones.obtener(ctx.params.id);
    if (!o) return TH.ui.vacio('Organización no encontrada', '', '<a class="btn btn--primario" href="#/fma/organizaciones">Volver</a>');
    const r = TH.api.organizaciones.resumen(o.id); const res = r.diag && r.diag.estado === 'completado' ? TH.api.diagnostico.calcular(r.diag) : null; const pr = TH.api.plan.resumen(r.plan);
    const usuarios = TH.api.usuarios.listar({ orgId: o.id }); const resp = usuarios.find(u => u.rol === 'organizacion');
    const intereses = TH.api.sello.interesesDeOrganizacion(o.id); const historial = TH.api.historial.listar({ entidadId: o.id });
    return TH.ui.migas([{ texto: 'Organizaciones', ruta: '/fma/organizaciones' }, { texto: o.nombre }]) +
      TH.ui.encabezado(o.nombre, TH.ui.badgeCatalogo(cat.estadosOrganizacion, o.estado) + ' ' + esc(o.sector) + ' · ' + esc(o.municipio) + ', ' + esc(o.departamento) + ' · ' + esc(TH.util.nombreCatalogo(cat.tamanos, o.tamano)), puede('*') ? (o.estado === 'activa' ? '<button type="button" class="btn btn--peligro" data-action="fma-org-estado" data-id="' + o.id + '" data-estado="suspendida">Suspender acceso</button>' : '<button type="button" class="btn btn--primario" data-action="fma-org-estado" data-id="' + o.id + '" data-estado="activa">Activar acceso</button>') : '') +
      (o.estado === 'suspendida' && o.estadoMotivo ? TH.ui.alerta('alerta', 'Organización suspendida', esc(o.estadoMotivo)) : '') +
      '<div class="grid grid-4">' + TH.ui.kpi('Autodiagnóstico', res ? res.global + '%' : r.diagnosticoPct + '%', res ? res.nivelGlobal.nombre : r.diagnosticoEstado === 'en-curso' ? 'en curso' : 'no iniciado') + TH.ui.kpi('Plan de acción', r.plan ? r.planPct + '%' : '—', r.plan ? pr.completadas + '/' + pr.total + ' completadas · ' + pr.vencidas.length + ' vencidas' : 'sin plan') + TH.ui.kpi('Evidencias', String(r.evidenciasTotal), 'registradas') + TH.ui.kpi('Colaboradores', String(r.colaboradoresActivos), r.colaboradoresInvitados + ' invitaciones · ' + r.modulosCompletados + ' módulos completados') + '</div>' +
      '<div class="grid grid-2 mt-4"><div class="card"><h3 class="card__titulo">Datos de registro</h3>' + TH.ui.dl([['Identificación', (o.tipoIdentificacion || '') + ' ' + (o.identificacion || '—')], ['Correo institucional', o.emailInstitucional || '—'], ['Teléfono', o.telefono || '—'], ['Responsable', o.responsable + (o.cargo ? ' · ' + TH.util.nombreCatalogo(cat.cargos, o.cargo) : '')], ['Correo del responsable', o.email], ['Registro', TH.util.fecha(o.fechaRegistro)], ['Cuenta', resp ? TH.util.nombreCatalogo(cat.estadosUsuario || [], resp.estado) || resp.estado : '—'], ['Correo verificado', resp ? (resp.correoVerificado ? 'Sí' : 'No') : '—'], ['Necesidades de acompañamiento', o.acompanamiento || '—']]) +
      '<h4 class="mt-4">Autorizaciones registradas</h4>' + (resp && resp.consentimientos && resp.consentimientos.length ? '<ul class="texto-sm">' + resp.consentimientos.map(c => '<li>' + esc(TH.util.nombreCatalogo(cat.tiposDocumentoLegal, c.tipo)) + ' v' + esc(c.version) + ' · ' + esc(TH.util.fecha(c.fecha)) + (c.modo === 'informado' ? ' · informado' : ' · autorización') + (c.transitorio ? ' · transitorio' : '') + (c.validado === false ? ' · aviso sin validar (prueba)' : '') + '</li>').join('') + '</ul>' : '<p class="texto-sm texto-2">Sin autorizaciones registradas.</p>') + '</div>' +
      '<div class="card"><h3 class="card__titulo">Lectura por dimensión</h3>' + (res ? TH.graficos.barras(res.dimensiones.map(d => ({ etiqueta: d.dim.corto, valor: d.puntaje }))) + '<p class="texto-xs texto-2 mt-2">Instrumento v' + esc(r.diag.instrumentoVersion) + ' · ciclo ' + (r.diag.ciclo || 1) + ' · completado ' + esc(TH.util.fecha(r.diag.fechaFin)) + '. Valores declarados por la organización.</p>' : '<p class="texto-2">Sin autodiagnóstico completado.</p>') + '</div></div>' +
      (r.plan ? '<div class="card mt-4"><h3 class="card__titulo">Plan de acción (' + pr.total + ' acciones · avance ' + pr.avance + '%)</h3>' + TH.ui.tabla([{ titulo: 'Objetivo', campo: 'objetivo' }, { titulo: 'Dimensión', render: a => esc(dimNombre(a.dim)) }, { titulo: 'Responsable', campo: 'responsable' }, { titulo: 'Fecha', render: a => esc(TH.util.fecha(a.fechaObjetivo)) }, { titulo: 'Estado', render: a => TH.ui.badgeCatalogo(cat.estadosAccion, a.estado) }, { titulo: 'Avance', render: a => TH.ui.progreso(a.avance) }, { titulo: 'Evid.', clase: 'num', render: a => String(r.evidencias.filter(e => e.accionId === a.id).length) }], r.plan.acciones, { caption: 'Acciones' }) + '</div>' : '') +
      '<div class="grid grid-2 mt-4"><div class="card"><h3 class="card__titulo">Sello Turquesa</h3>' + (intereses.length ? intereses.map(i => '<p class="texto-sm">' + esc(TH.util.fecha(i.fecha)) + ' · ' + TH.ui.badgeCatalogo(cat.estadosInteres, i.estado) + ' · <a href="#/fma/sello?id=' + i.id + '">ver</a></p>').join('') : '<p class="texto-sm texto-2">Sin manifestaciones de interés.</p>') + '</div>' +
      '<div class="card"><h3 class="card__titulo">Trazabilidad</h3>' + TH.ui.historial(historial.slice(0, 8).map(h => ({ fecha: h.fecha, actor: nombreUsuario(h.actorId), accion: h.accion }))) + '</div></div>';
  }

  /* ================= INSTRUMENTO Y DIAGNÓSTICOS ================= */
  function diagnosticos() {
    const todas = TH.api.diagnostico.todas(); const activas = TH.api.diagnostico.preguntas(); const versiones = TH.api.configuracion.versionesInstrumento(); const conf = TH.api.configuracion.obtener(); const alc = conf.instrumentoAlcance || {};
    const diags = TH.api.diagnostico.listar(); const edita = puede('instrumento:editar') || puede('*');
    return TH.ui.encabezado('Instrumento y diagnósticos', 'Versión vigente v' + esc(instr.version) + ' · ' + activas.length + ' preguntas activas de ' + todas.length + ' en el banco. Un cambio de alcance aplica a los autodiagnósticos nuevos o en curso; los ya completados conservan su resultado con la versión respondida.', edita ? '<button type="button" class="btn btn--secundario" data-action="fma-instr-version">Crear versión borrador</button>' : '') +
      TH.ui.alerta('info', 'Estado del instrumento', esc(instr.nota) + ' Estado editorial: <strong>' + esc(TH.util.nombreCatalogo(cat.estadosContenido, instr.estado)) + '</strong>. La revisión psicométrica y jurídica definitivas corresponden a las personas autorizadas; la plataforma no las registra automáticamente.') +
      '<div class="grid grid-3 mb-4">' + TH.ui.kpi('Diagnósticos iniciados', String(diags.length)) + TH.ui.kpi('Completados', String(diags.filter(d => d.estado === 'completado').length)) + TH.ui.kpi('Versiones', String(versiones.length + 1), 'incluida la vigente') + '</div>' +
      '<div class="card"><h3 class="card__titulo">Versiones del instrumento</h3>' + TH.ui.tabla([{ titulo: 'Versión', render: v => 'v' + esc(v.version) }, { titulo: 'Estado', render: v => TH.ui.badge(v.estado === 'vigente' ? 'Vigente' : 'Borrador', v.estado === 'vigente' ? 'exito' : 'alerta') }, { titulo: 'Fecha', render: v => esc(TH.util.fecha(v.fecha)) }, { titulo: 'Preguntas activas', clase: 'num', render: v => String(v.preguntasActivas) }, { titulo: 'Revisiones', render: v => v.revision ? ['tecnica', 'psicosocial', 'juridica'].map(k => esc(k) + ': ' + esc(v.revision[k] || 'pendiente')).join(' · ') : '—' }, { titulo: 'Nota', render: v => esc(v.nota || '') }], [{ version: instr.version, estado: 'vigente', fecha: instr.fecha, preguntasActivas: activas.length, revision: instr.revision, nota: 'Versión en uso por las organizaciones.' }].concat(versiones), { caption: 'Versiones' }) + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Banco de preguntas</h3><p class="card__sub mb-3">Cada pregunta indica dimensión, capacidad, fundamento y evidencia esperada. El alcance "activa" integra la pregunta en el autodiagnóstico; "reserva" la mantiene en el banco.</p>' +
      TH.ui.tabla([{ titulo: '#', render: p => esc(p.id) }, { titulo: 'Pregunta', render: p => '<strong>' + esc(p.texto) + '</strong><div class="texto-xs texto-2 mt-1">' + esc(p.capacidad) + '</div><details class="ayuda"><summary>Fundamento y evidencia</summary><div class="ayuda__cuerpo texto-sm">' + esc(p.justificacion) + '<br><strong>Evidencia:</strong> ' + esc(p.evidenciaEjemplo) + '<br><strong>Interpretación:</strong> ' + esc(p.reglaInterpretacion) + TH.ui.referencias(p.fuentes) + '</div></details>' }, { titulo: 'Dimensión', render: p => TH.ui.badge(dimNombre(p.dim), 'turquesa') }, { titulo: 'Alcance', render: p => { const a = alc[p.id] || p.alcance; return TH.ui.badge(a === 'activa' ? 'Activa' : 'Reserva', a === 'activa' ? 'exito' : 'neutro') + (alc[p.id] && alc[p.id] !== p.alcance ? ' <span class="texto-xs texto-2">(ajustado por la FMA)</span>' : ''); } }, { titulo: '', clase: 'acciones', render: p => edita ? '<button type="button" class="btn btn--terciario btn--sm" data-action="fma-instr-alcance" data-id="' + p.id + '" data-alcance="' + ((alc[p.id] || p.alcance) === 'activa' ? 'reserva' : 'activa') + '">' + ((alc[p.id] || p.alcance) === 'activa' ? 'Pasar a reserva' : 'Activar') + '</button>' : '' }], todas, { caption: 'Banco de preguntas' }) + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo">Diagnósticos por organización</h3>' + TH.ui.tabla([{ titulo: 'Organización', render: d => { const o = TH.api.organizaciones.obtener(d.orgId); return o ? '<a href="#/fma/organizaciones/detalle?id=' + o.id + '">' + esc(o.nombre) + '</a>' : esc(d.orgId); } }, { titulo: 'Versión', render: d => 'v' + esc(d.instrumentoVersion) }, { titulo: 'Ciclo', clase: 'num', render: d => String(d.ciclo || 1) }, { titulo: 'Estado', render: d => TH.ui.badge(d.estado === 'completado' ? 'Completado' : 'En curso', d.estado === 'completado' ? 'exito' : 'info') }, { titulo: 'Valor orientativo', clase: 'num', render: d => d.estado === 'completado' ? TH.api.diagnostico.calcular(d).global + '%' : '—' }, { titulo: 'Fecha', render: d => esc(TH.util.fecha(d.fechaFin || d.ultimoGuardado)) }], diags, { caption: 'Diagnósticos', vacioTitulo: 'Sin diagnósticos', vacioTexto: 'Ninguna organización ha iniciado el autodiagnóstico.' }) + '</div>';
  }

  /* ================= PLANES ================= */
  function planes() {
    const planes = TH.api.plan.listar(); const acciones = planes.flatMap(p => p.acciones.map(a => Object.assign({ orgId: p.orgId }, a)));
    const porEstado = cat.estadosAccion.map(e => ({ etiqueta: e.nombre, valor: acciones.filter(a => a.estado === e.id).length }));
    return TH.ui.encabezado('Planes de acción', 'Seguimiento agregado de los planes de las organizaciones.') +
      '<div class="grid grid-3 mb-4">' + TH.ui.kpi('Planes', String(planes.length)) + TH.ui.kpi('Acciones', String(acciones.length), TH.util.pct(acciones.filter(a => a.estado === 'completada').length, acciones.length) + '% completadas') + TH.ui.kpi('Atrasadas', String(acciones.filter(a => a.estado === 'atrasada').length)) + '</div>' +
      '<div class="grid grid-2"><div class="card"><h3 class="card__titulo">Acciones por estado</h3>' + TH.graficos.barras(porEstado, { max: Math.max(1, acciones.length), sufijo: '' }) + '</div><div class="card"><h3 class="card__titulo">Acciones por dimensión</h3>' + TH.graficos.barras(instr.dimensiones.map(d => ({ etiqueta: d.corto, valor: acciones.filter(a => a.dim === d.id).length })), { max: Math.max(1, acciones.length), sufijo: '' }) + '</div></div>' +
      '<div class="card mt-4">' + TH.ui.tabla([{ titulo: 'Organización', render: p => { const o = TH.api.organizaciones.obtener(p.orgId); return o ? '<a href="#/fma/organizaciones/detalle?id=' + o.id + '">' + esc(o.nombre) + '</a>' : esc(p.orgId); } }, { titulo: 'Creado', render: p => esc(TH.util.fecha(p.fechaCreacion)) }, { titulo: 'Acciones', clase: 'num', render: p => String(p.acciones.length) }, { titulo: 'Completadas', clase: 'num', render: p => String(p.acciones.filter(a => a.estado === 'completada').length) }, { titulo: 'Vencidas', clase: 'num', render: p => { const n = TH.api.plan.resumen(p).vencidas.length; return n ? TH.ui.badge(String(n), 'error') : '0'; } }, { titulo: 'Avance', render: p => TH.ui.progreso(TH.api.plan.resumen(p).avance) }], planes, { caption: 'Planes', vacioTitulo: 'Sin planes', vacioTexto: 'Ninguna organización ha creado un plan.' }) + '</div>';
  }

  /* ================= CONTENIDOS (EDITORIAL) ================= */
  function contenidos(ctx) {
    if (ctx.params.id) return contenidoDetalle(ctx.params.id);
    const lista = TH.api.contenidos.listar({ q: ui.contQ, estado: ui.contEstado, categoria: ui.contCat });
    const cuentas = cat.estadosContenido.map(e => ({ e, n: TH.api.contenidos.listar({ estado: e.id }).length }));
    return TH.ui.encabezado('Contenidos', 'Gestión editorial de la biblioteca. Flujo: borrador → revisión técnica → revisión jurídica → revisión psicosocial → aprobado → publicado. Ninguna aprobación es automática.', puede('contenidos:editar') ? '<button type="button" class="btn btn--primario" data-action="fma-contenido-nuevo">' + ic('mas') + ' Nuevo contenido</button>' : '') +
      '<div class="flex gap-2 wrap mb-4">' + cuentas.map(c => '<button type="button" class="btn btn--sm ' + (ui.contEstado === c.e.id ? 'btn--primario' : 'btn--secundario') + '" data-action="fma-cont-estado-filtro" data-estado="' + (ui.contEstado === c.e.id ? '' : c.e.id) + '">' + esc(c.e.nombre) + ' (' + c.n + ')</button>').join('') + '</div>' +
      '<div class="filtros"><div class="buscador campo">' + ic('lupa') + '<label class="sr-only" for="cq">Buscar</label><input class="input" id="cq" type="search" placeholder="Título, tema, categoría" value="' + esc(ui.contQ) + '" data-input="fma-cont-q"></div><div class="campo"><label class="sr-only" for="cc">Categoría</label><select class="select" id="cc" data-change="fma-cont-cat"><option value="">Todas las categorías</option>' + cat.categoriasContenido.map(c => '<option ' + (ui.contCat === c ? 'selected' : '') + '>' + esc(c) + '</option>').join('') + '</select></div></div>' +
      TH.ui.tabla([{ titulo: 'Contenido', render: c => '<a href="#/fma/contenidos?id=' + c.id + '"><strong>' + esc(c.titulo) + '</strong></a><div class="texto-xs texto-2">' + esc(c.categoria) + ' · ' + esc(c.tema) + ' · v' + esc(c.version) + (c.referencial ? ' · referencial' : '') + '</div>' }, { titulo: 'Estado', render: c => TH.ui.badgeCatalogo(cat.estadosContenido, c.estado) }, { titulo: 'Técnica', render: c => TH.ui.badgeCatalogo(cat.estadosRevision, c.revisionTecnica) }, { titulo: 'Jurídica', render: c => TH.ui.badgeCatalogo(cat.estadosRevision, c.revisionJuridica) }, { titulo: 'Psicosocial', render: c => TH.ui.badgeCatalogo(cat.estadosRevision, c.revisionPsicosocial || 'no-aplica') }, { titulo: 'Público', render: c => (c.publico || []).map(p => TH.ui.badge(p === 'organizacion' ? 'Org.' : 'Colab.', 'neutro')).join(' ') }, { titulo: 'Fecha', render: c => esc(TH.util.fecha(c.fecha)) }, { titulo: '', clase: 'acciones', render: c => '<a class="btn btn--terciario btn--sm" href="#/fma/contenidos?id=' + c.id + '">Abrir</a>' }], lista, { caption: 'Contenidos', vacioTitulo: 'Sin contenidos', vacioTexto: 'No hay contenidos para estos filtros.' });
  }
  function contenidoDetalle(id) {
    const c = TH.api.contenidos.obtener(id);
    if (!c) return TH.ui.vacio('Contenido no encontrado', '', '<a class="btn btn--primario" href="#/fma/contenidos">Volver</a>');
    const transiciones = { borrador: [['en-revision-tecnica', 'Enviar a revisión técnica', 'contenidos:editar']], 'en-revision-tecnica': [['en-revision-juridica', 'Pasar a revisión jurídica', 'contenidos:revisar-tecnica'], ['en-revision-psicosocial', 'Pasar a revisión psicosocial', 'contenidos:revisar-tecnica'], ['aprobado', 'Aprobar', 'contenidos:aprobar']], 'en-revision-juridica': [['en-revision-psicosocial', 'Pasar a revisión psicosocial', 'contenidos:revisar-tecnica'], ['aprobado', 'Aprobar', 'contenidos:aprobar']], 'en-revision-psicosocial': [['aprobado', 'Aprobar', 'contenidos:aprobar']], aprobado: [['publicado', 'Publicar', 'contenidos:publicar']], publicado: [['archivado', 'Archivar', 'contenidos:publicar']], archivado: [['borrador', 'Reabrir como borrador', 'contenidos:editar']] }[c.estado] || [];
    const botones = transiciones.filter(t => puede(t[2])).map(t => '<button type="button" class="btn ' + (t[0] === 'publicado' ? 'btn--primario' : 'btn--secundario') + '" data-action="fma-contenido-estado" data-id="' + c.id + '" data-estado="' + t[0] + '">' + esc(t[1]) + '</button>').join('');
    const revisiones = [['tecnica', 'Revisión técnica', c.revisionTecnica, 'contenidos:revisar-tecnica'], ['juridica', 'Revisión jurídica', c.revisionJuridica, 'contenidos:revisar-juridica'], ['psicosocial', 'Revisión psicosocial', c.revisionPsicosocial || 'no-aplica', 'contenidos:revisar-psicosocial']];
    return TH.ui.migas([{ texto: 'Contenidos', ruta: '/fma/contenidos' }, { texto: c.titulo }]) +
      TH.ui.encabezado(c.titulo, TH.ui.badgeCatalogo(cat.estadosContenido, c.estado) + ' ' + TH.ui.badge(c.categoria, 'violeta') + ' ' + TH.ui.badge('v' + c.version, 'neutro') + (c.referencial ? ' ' + TH.ui.badge('Referencial', 'alerta') : ''), (puede('contenidos:editar') ? '<button type="button" class="btn btn--secundario" data-action="fma-contenido-editar" data-id="' + c.id + '">' + ic('editar') + ' Editar</button>' : '') + botones) +
      '<div class="grid grid-sidebar"><div>' + TH.vistasCompartidas.fichaContenido(c) + '</div><aside>' +
      '<div class="card"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Revisiones</h3><p class="texto-xs texto-2">Cada revisión solo puede registrarla la persona con el permiso correspondiente. La aprobación exige las revisiones aplicables aprobadas.</p>' +
      revisiones.map(r => '<div class="mt-3"><div class="flex justify-between items-center gap-2"><strong class="texto-sm">' + esc(r[1]) + '</strong>' + TH.ui.badgeCatalogo(cat.estadosRevision, r[2]) + '</div>' + (r[2] !== 'no-aplica' && puede(r[3]) ? '<div class="flex gap-1 mt-1 wrap"><button type="button" class="btn btn--terciario btn--sm" data-action="fma-revision" data-id="' + c.id + '" data-tipo="' + r[0] + '" data-resultado="aprobada">Aprobar</button><button type="button" class="btn btn--terciario btn--sm" data-action="fma-revision" data-id="' + c.id + '" data-tipo="' + r[0] + '" data-resultado="cambios-requeridos">Pedir cambios</button><button type="button" class="btn btn--terciario btn--sm" data-action="fma-revision" data-id="' + c.id + '" data-tipo="' + r[0] + '" data-resultado="en-curso">En curso</button></div>' : '') + '</div>').join('') +
      (c.revisiones && c.revisiones.length ? '<hr><h4 class="texto-sm">Registro de revisiones</h4>' + c.revisiones.slice().reverse().map(r => '<p class="texto-xs mb-2"><strong>' + esc(r.tipo) + '</strong> · ' + esc(TH.util.nombreCatalogo(cat.estadosRevision, r.resultado)) + ' · ' + esc(r.revisor) + ' · ' + esc(TH.util.fecha(r.fecha)) + ' · v' + esc(r.version) + (r.observaciones ? '<br>' + esc(r.observaciones) : '') + '</p>').join('') : '') + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Historial de versiones</h3>' + TH.ui.historial((c.historial || []).map(h => ({ fecha: h.fecha, actor: h.actor, accion: h.accion + ' (v' + h.version + ')' }))) + '</div></aside></div>';
  }
  function formularioContenido(c) {
    c = c || {};
    const secciones = c.secciones && c.secciones.length ? c.secciones : [{ titulo: 'Objetivo', cuerpo: [] }, { titulo: 'Conceptos', cuerpo: [] }, { titulo: 'Desarrollo técnico', cuerpo: [] }, { titulo: 'Aplicación en la organización colombiana', cuerpo: [] }, { titulo: 'Situación práctica', cuerpo: [] }, { titulo: 'Acciones recomendadas', cuerpo: [] }, { titulo: 'Errores frecuentes', cuerpo: [] }, { titulo: 'Herramienta o lista de verificación', cuerpo: [] }];
    return '<form id="form-contenido" data-form="fma-contenido" data-id="' + esc(c.id || '') + '" novalidate>' + TH.ui.campo({ name: 'titulo', label: 'Título', required: true, valor: c.titulo || '' }) +
      '<div class="form-fila">' + TH.ui.campo({ name: 'categoria', label: 'Categoría', tipo: 'select', required: true, opciones: cat.categoriasContenido, valor: c.categoria || '' }) + TH.ui.campo({ name: 'tema', label: 'Tema', required: true, valor: c.tema || '' }) + '</div>' +
      TH.ui.campo({ name: 'descripcion', label: 'Descripción breve', tipo: 'textarea', rows: 2, required: true, valor: c.descripcion || '' }) + TH.ui.campo({ name: 'objetivo', label: 'Objetivo', tipo: 'textarea', rows: 2, valor: c.objetivo || '' }) +
      '<fieldset><legend class="texto-sm">Secciones (un párrafo por línea; las líneas que empiezan con "- " forman una lista)</legend>' + secciones.map((s, i) => '<div class="campo"><label class="campo__label" for="sec-' + i + '">' + esc(s.titulo) + '</label><input type="hidden" name="secTitulo" value="' + esc(s.titulo) + '"><textarea class="textarea" id="sec-' + i + '" name="secCuerpo" rows="3">' + esc((s.cuerpo || []).concat((s.lista || []).map(l => '- ' + l)).join('\n')) + '</textarea></div>').join('') + '</fieldset>' +
      TH.ui.campo({ name: 'referencias', label: 'Referencias (códigos del registro de fuentes separados por coma, p. ej. F-04, F-22)', valor: (c.referencias || []).join(', '), ayuda: 'Solo se admiten códigos existentes en el registro de fuentes verificadas.' }) +
      '<fieldset><legend class="texto-sm">Público</legend>' + TH.ui.check('publico', 'Organizaciones', (c.publico || ['organizacion']).includes('organizacion'), 'organizacion') + TH.ui.check('publico', 'Colaboradores', (c.publico || []).includes('colaborador'), 'colaborador') + '</fieldset>' +
      '<fieldset><legend class="texto-sm">Revisiones aplicables</legend>' + TH.ui.check('aplicaJuridica', 'Requiere revisión jurídica', c.id ? c.revisionJuridica !== 'no-aplica' : true) + TH.ui.check('aplicaPsicosocial', 'Requiere revisión psicosocial', c.id ? (c.revisionPsicosocial || 'no-aplica') !== 'no-aplica' : true) + TH.ui.check('referencial', 'Marcar como referencial (modelo orientativo pendiente de validación jurídica)', !!c.referencial) + '</fieldset>' +
      '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>';
  }
  function leerSecciones(form) {
    const titulos = [...form.querySelectorAll('input[name=secTitulo]')].map(i => i.value); const cuerpos = [...form.querySelectorAll('textarea[name=secCuerpo]')].map(t => t.value);
    return titulos.map((t, i) => { const lineas = cuerpos[i].split('\n').map(x => x.trim()).filter(Boolean); return { titulo: t, cuerpo: lineas.filter(l => !l.startsWith('- ')), lista: lineas.filter(l => l.startsWith('- ')).map(l => l.slice(2)) }; }).filter(s => s.cuerpo.length || s.lista.length);
  }

  /* ================= FORMACIÓN ================= */
  function formacionAdmin() {
    const tot = TH.api.formacion.totales(); const ultimas = TH.api.modulos.ultimas(); const todas = TH.api.modulos.listar();
    const publicados = TH.api.modulos.publicados().length;
    return TH.ui.encabezado('Formación · módulos de sensibilización', 'Gestión editorial de los módulos: revisión, edición, aprobación, versiones, publicación, retiro y sustitución. Las organizaciones y colaboradores solo reciben versiones publicadas.') +
      '<div class="grid grid-4 mb-4">' + TH.ui.kpi('Módulos', String(ultimas.length), todas.length + ' versiones en total') + TH.ui.kpi('Publicados', String(publicados), publicados ? 'disponibles para organizaciones' : 'ninguno disponible todavía') + TH.ui.kpi('Participantes', String(tot.participantes)) + TH.ui.kpi('Módulos completados', String(tot.completados)) + '</div>' +
      (publicados === 0 ? TH.ui.alerta('info', 'Ningún módulo está publicado', 'Hasta que una versión complete las revisiones técnica, jurídica y psicosocial, sea aprobada y publicada, las organizaciones no pueden asignar módulos a sus colaboradores.') : '') +
      ultimas.map(m => { const vs = TH.api.modulos.versiones(m.moduloId); const pub = TH.api.modulos.publicado(m.moduloId); const p = TH.store.get().progresoFormativo.filter(x => x.moduloId === m.moduloId); const comp = p.filter(x => x.estado === 'completado');
        return '<div class="card mb-3"><div class="modulo-card"><div class="modulo-card__num modulo-card__num--' + m.color + '">' + m.orden + '</div><div class="grow"><div class="flex justify-between gap-2 wrap"><h3 class="card__titulo">' + esc(m.titulo) + '</h3><span>' + (pub ? TH.ui.badge('Publicada v' + pub.version, 'exito') + ' ' : TH.ui.badge('Sin versión publicada', 'alerta') + ' ') + (m.id !== (pub && pub.id) ? TH.ui.badge('v' + m.version + ': ' + TH.util.nombreCatalogo(cat.estadosModulo, m.estado), 'neutro') : '') + '</span></div><p class="card__sub">' + esc(m.resumen) + '</p><div class="texto-xs texto-2 mt-2">' + esc(m.duracion) + ' · ' + m.lecciones.length + ' lecciones · ' + m.quiz.length + ' preguntas · ' + vs.length + ' versión(es) · ' + p.length + ' participantes · ' + comp.length + ' completados</div>' +
          '<div class="flex gap-2 wrap mt-3">' + vs.map(v => '<a class="btn btn--terciario btn--sm" href="#/fma/formacion/version?id=' + v.id + '">v' + esc(v.version) + ' · ' + esc(TH.util.nombreCatalogo(cat.estadosModulo, v.estado)) + '</a>').join('') + (puede('formacion:editar') && !vs.some(v => !['publicado', 'archivado', 'retirado'].includes(v.estado)) ? '<button type="button" class="btn btn--secundario btn--sm" data-action="fma-modulo-nueva-version" data-modulo="' + m.moduloId + '">' + ic('mas') + ' Nueva versión</button>' : '') + '</div></div></div></div>'; }).join('') +
      TH.ui.alerta('neutra', 'Reglas editoriales', 'Una versión publicada no se edita: se crea una nueva versión, que vuelve a pasar por las tres revisiones; al publicarla sustituye a la anterior (que queda archivada). "Retirar" saca el módulo del catálogo sin borrar el progreso ya registrado. Ninguna revisión se registra automáticamente.');
  }
  function formacionVersion(ctx) {
    const m = TH.api.modulos.obtenerVersion(ctx.params.id);
    if (!m) return TH.ui.vacio('Versión no encontrada', '', '<a class="btn btn--primario" href="#/fma/formacion">Volver</a>');
    const editable = puede('formacion:editar') && !['publicado', 'archivado', 'retirado'].includes(m.estado);
    const transiciones = { borrador: [['en-revision-tecnica', 'Enviar a revisión técnica', 'formacion:editar']], 'en-revision-tecnica': [['en-revision-juridica', 'Pasar a revisión jurídica', 'formacion:revisar-tecnica'], ['en-revision-psicosocial', 'Pasar a revisión psicosocial', 'formacion:revisar-tecnica'], ['aprobado', 'Aprobar', 'formacion:aprobar']], 'en-revision-juridica': [['en-revision-psicosocial', 'Pasar a revisión psicosocial', 'formacion:revisar-tecnica'], ['aprobado', 'Aprobar', 'formacion:aprobar']], 'en-revision-psicosocial': [['aprobado', 'Aprobar', 'formacion:aprobar']], aprobado: [['publicado', 'Publicar (sustituye a la versión publicada)', 'formacion:publicar']], publicado: [['retirado', 'Retirar del catálogo', 'formacion:publicar']], retirado: [['publicado', 'Volver a publicar', 'formacion:publicar']], archivado: [] }[m.estado] || [];
    const botones = transiciones.filter(t => puede(t[2])).map(t => '<button type="button" class="btn ' + (t[0] === 'publicado' ? 'btn--primario' : t[0] === 'retirado' ? 'btn--peligro' : 'btn--secundario') + '" data-action="fma-modulo-estado" data-id="' + m.id + '" data-estado="' + t[0] + '">' + esc(t[1]) + '</button>').join('');
    const revisiones = [['tecnica', 'Revisión técnica', m.revisionTecnica, 'formacion:revisar-tecnica'], ['juridica', 'Revisión jurídica', m.revisionJuridica, 'formacion:revisar-juridica'], ['psicosocial', 'Revisión psicosocial', m.revisionPsicosocial, 'formacion:revisar-psicosocial']];
    const cerrado = ['publicado', 'archivado', 'retirado'].includes(m.estado);
    return TH.ui.migas([{ texto: 'Formación', ruta: '/fma/formacion' }, { texto: 'Módulo ' + m.orden + ' · v' + m.version }]) +
      TH.ui.encabezado(m.titulo, TH.ui.badge('Versión ' + m.version, 'neutro') + ' ' + TH.ui.badgeCatalogo(cat.estadosModulo, m.estado) + (m.publicacion ? ' <span class="texto-xs texto-2">Publicada el ' + esc(TH.util.fecha(m.publicacion.fecha)) + ' por ' + esc(m.publicacion.por) + '</span>' : ''), (editable ? '<button type="button" class="btn btn--secundario" data-action="fma-modulo-editar" data-id="' + m.id + '">' + ic('editar') + ' Editar</button>' : '') + botones) +
      '<div class="grid grid-sidebar"><div><div class="card"><h3 class="card__titulo">Objetivos</h3><ul>' + m.objetivos.map(o => '<li>' + esc(o) + '</li>').join('') + '</ul><p class="texto-sm texto-2">' + esc(m.resumen) + ' · ' + esc(m.duracion) + '</p></div>' +
      m.lecciones.map((l, i) => '<details class="card mt-3"><summary><strong>Lección ' + (i + 1) + ' · ' + esc(l.titulo) + '</strong> <span class="texto-2 texto-sm">(' + esc(l.tipo) + ')</span></summary><div class="mt-3">' + (l.cuerpo || []).map(t => '<p>' + esc(t) + '</p>').join('') + (l.situacion ? '<div class="situacion"><div class="situacion__label">Situación práctica</div>' + esc(l.situacion) + '</div>' : '') + (l.actividad ? '<div class="card card--suave card--compacta mt-3"><strong>' + esc(l.actividad.titulo) + '</strong><p class="texto-sm">' + esc(l.actividad.instrucciones) + '</p><ol class="texto-sm mb-0">' + (l.actividad.preguntas || []).map(q => '<li>' + esc(q) + '</li>').join('') + '</ol></div>' : '') + (l.tarjeta ? '<div class="tarjeta-info tarjeta-info--' + esc(l.tarjeta.tipo) + ' mt-3">' + esc(l.tarjeta.texto) + '</div>' : '') + '<div class="mt-2"><strong class="texto-sm">Referencias</strong>' + TH.ui.referencias(l.referencias) + '</div></div></details>').join('') +
      '<details class="card mt-3"><summary><strong>Ejercicio de apropiación (' + m.quiz.length + ' preguntas)</strong></summary><ol class="mt-3">' + m.quiz.map(q => '<li class="mb-3"><strong>' + esc(q.texto) + '</strong><ul class="texto-sm">' + q.opciones.map(o => '<li>' + (o.id === q.correcta ? '✓ ' : '') + esc(o.texto) + '</li>').join('') + '</ul><div class="texto-xs texto-2">Correcta: ' + esc(q.retro.ok) + '<br>Incorrecta: ' + esc(q.retro.no) + (q.referencia ? '<br>Referencia: ' + esc([].concat(q.referencia).join(', ')) : '') + '</div></li>').join('') + '</ol></details>' +
      '<div class="card mt-3"><h3 class="card__titulo">Bibliografía y recursos</h3>' + TH.ui.referencias(m.bibliografia) + '<p class="texto-sm texto-2 mb-0">Recursos vinculados: ' + esc((m.recursos || []).join(', ') || '—') + '</p></div></div>' +
      '<aside><div class="card"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Revisiones de esta versión</h3><p class="texto-xs texto-2">Cada revisión la registra únicamente la persona con el permiso correspondiente. Para aprobar y publicar se requieren las tres revisiones aprobadas.</p>' +
      revisiones.map(r => '<div class="mt-3"><div class="flex justify-between items-center gap-2"><strong class="texto-sm">' + esc(r[1]) + '</strong>' + TH.ui.badgeCatalogo(cat.estadosRevision, r[2]) + '</div>' + (!cerrado && puede(r[3]) ? '<div class="flex gap-1 mt-1 wrap"><button type="button" class="btn btn--terciario btn--sm" data-action="fma-modulo-revision" data-id="' + m.id + '" data-tipo="' + r[0] + '" data-resultado="aprobada">Aprobar</button><button type="button" class="btn btn--terciario btn--sm" data-action="fma-modulo-revision" data-id="' + m.id + '" data-tipo="' + r[0] + '" data-resultado="cambios-requeridos">Pedir cambios</button><button type="button" class="btn btn--terciario btn--sm" data-action="fma-modulo-revision" data-id="' + m.id + '" data-tipo="' + r[0] + '" data-resultado="en-curso">En curso</button></div>' : '') + '</div>').join('') +
      (m.revisiones && m.revisiones.length ? '<hr><h4 class="texto-sm">Historial de aprobaciones</h4>' + m.revisiones.slice().reverse().map(r => '<p class="texto-xs mb-2"><strong>' + esc(r.tipo) + '</strong> · ' + esc(TH.util.nombreCatalogo(cat.estadosRevision, r.resultado)) + ' · ' + esc(r.revisor) + ' · ' + esc(TH.util.fecha(r.fecha)) + ' · v' + esc(r.version) + (r.observaciones ? '<br>' + esc(r.observaciones) : '') + '</p>').join('') : '') + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Historial de la versión</h3>' + TH.ui.historial((m.historial || []).map(h => ({ fecha: h.fecha, actor: h.actor, accion: h.accion + ' (v' + h.version + ')' }))) + '</div>' +
      '<div class="card mt-4"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Otras versiones</h3>' + TH.api.modulos.versiones(m.moduloId).map(v => '<p class="texto-sm mb-1">' + (v.id === m.id ? '<strong>' : '<a href="#/fma/formacion/version?id=' + v.id + '">') + 'v' + esc(v.version) + (v.id === m.id ? '</strong>' : '</a>') + ' · ' + TH.ui.badgeCatalogo(cat.estadosModulo, v.estado) + ' · ' + esc(TH.util.fecha(v.fecha)) + '</p>').join('') + '</div></aside></div>';
  }
  /** Editor estructurado de una versión de módulo (lecciones, ejercicio, bibliografía). */
  function formularioModulo(m) {
    const lec = (l, i) => '<details class="card card--compacta mb-3" ' + (i === 0 ? 'open' : '') + '><summary><strong>Lección ' + (i + 1) + '</strong></summary><div class="mt-3"><input type="hidden" name="lecId" value="' + esc(l.id) + '"><div class="form-fila">' + TH.ui.campo({ name: 'lecTitulo', id: 'lt' + i, label: 'Título', required: true, valor: l.titulo }) + TH.ui.campo({ name: 'lecTipo', id: 'ltp' + i, label: 'Tipo', valor: l.tipo }) + '</div>' + TH.ui.campo({ name: 'lecCuerpo', id: 'lc' + i, label: 'Desarrollo (un párrafo por línea)', tipo: 'textarea', rows: 6, required: true, valor: (l.cuerpo || []).join('\n') }) + TH.ui.campo({ name: 'lecSituacion', id: 'ls' + i, label: 'Situación práctica (ficticia)', tipo: 'textarea', rows: 3, valor: l.situacion || '' }) + TH.ui.campo({ name: 'lecActividad', id: 'la' + i, label: 'Actividad de reflexión: instrucciones en la primera línea; una pregunta por línea después', tipo: 'textarea', rows: 4, valor: l.actividad ? [l.actividad.instrucciones].concat(l.actividad.preguntas || []).join('\n') : '' }) + TH.ui.campo({ name: 'lecTarjeta', id: 'lk' + i, label: 'Idea clave', valor: l.tarjeta ? l.tarjeta.texto : '' }) + TH.ui.campo({ name: 'lecRefs', id: 'lr' + i, label: 'Referencias (códigos F-xx separados por coma)', valor: (l.referencias || []).join(', ') }) + '</div></details>';
    const preg = (q, i) => '<details class="card card--compacta mb-3"><summary><strong>Pregunta ' + (i + 1) + '</strong></summary><div class="mt-3"><input type="hidden" name="qId" value="' + esc(q.id) + '">' + TH.ui.campo({ name: 'qTexto', id: 'qt' + i, label: 'Enunciado', required: true, valor: q.texto }) + '<div class="form-fila">' + ['a', 'b', 'c', 'd'].map(k => { const o = q.opciones.find(x => x.id === k) || { texto: '' }; return TH.ui.campo({ name: 'qOp' + k, id: 'qo' + k + i, label: 'Opción ' + k.toUpperCase(), valor: o.texto }); }).join('') + '</div><div class="form-fila--3 form-fila">' + TH.ui.campo({ name: 'qCorrecta', id: 'qc' + i, label: 'Correcta', tipo: 'select', opciones: ['a', 'b', 'c', 'd'].map(k => ({ id: k, nombre: k.toUpperCase() })), valor: q.correcta }) + TH.ui.campo({ name: 'qRef', id: 'qr' + i, label: 'Referencia (F-xx)', valor: [].concat(q.referencia || []).join(', ') }) + '</div>' + TH.ui.campo({ name: 'qRetroOk', id: 'qk' + i, label: 'Retroalimentación si acierta', tipo: 'textarea', rows: 2, valor: q.retro.ok }) + TH.ui.campo({ name: 'qRetroNo', id: 'qn' + i, label: 'Retroalimentación si falla', tipo: 'textarea', rows: 2, valor: q.retro.no }) + '</div></details>';
    return '<form id="form-modulo" data-form="fma-modulo" data-id="' + m.id + '" novalidate>' + TH.ui.campo({ name: 'titulo', label: 'Título', required: true, valor: m.titulo }) + '<div class="form-fila">' + TH.ui.campo({ name: 'duracion', label: 'Duración estimada', required: true, valor: m.duracion }) + TH.ui.campo({ name: 'bibliografia', label: 'Bibliografía (códigos F-xx separados por coma)', required: true, valor: (m.bibliografia || []).join(', ') }) + '</div>' + TH.ui.campo({ name: 'resumen', label: 'Resumen', tipo: 'textarea', rows: 2, required: true, valor: m.resumen }) + TH.ui.campo({ name: 'objetivos', label: 'Objetivos de aprendizaje (uno por línea)', tipo: 'textarea', rows: 4, required: true, valor: (m.objetivos || []).join('\n') }) + TH.ui.campo({ name: 'recursos', label: 'Recursos de la biblioteca vinculados (ids separados por coma)', valor: (m.recursos || []).join(', ') }) +
      '<h3 class="mt-4">Lecciones</h3>' + m.lecciones.map(lec).join('') + '<h3 class="mt-4">Ejercicio de apropiación</h3>' + m.quiz.map(preg).join('') + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>';
  }
  function leerModulo(form) {
    const val = (n) => [...form.querySelectorAll('[name=' + n + ']')].map(x => x.value);
    const lineas = (t) => t.split('\n').map(x => x.trim()).filter(Boolean); const refs = (t) => t.split(',').map(x => x.trim().toUpperCase()).filter(Boolean);
    const ids = val('lecId'); const lecciones = ids.map((id, i) => { const act = lineas(val('lecActividad')[i] || ''); const tarj = (val('lecTarjeta')[i] || '').trim(); return { id, tipo: (val('lecTipo')[i] || 'Concepto').trim(), titulo: val('lecTitulo')[i].trim(), cuerpo: lineas(val('lecCuerpo')[i] || ''), situacion: (val('lecSituacion')[i] || '').trim(), actividad: act.length ? { titulo: 'Actividad de reflexión', instrucciones: act[0], preguntas: act.slice(1) } : null, tarjeta: tarj ? { tipo: 'turquesa', texto: tarj } : null, referencias: refs(val('lecRefs')[i] || '') }; });
    const qids = val('qId'); const quiz = qids.map((id, i) => ({ id, texto: val('qTexto')[i].trim(), opciones: ['a', 'b', 'c', 'd'].map(k => ({ id: k, texto: (val('qOp' + k)[i] || '').trim() })).filter(o => o.texto), correcta: val('qCorrecta')[i], retro: { ok: (val('qRetroOk')[i] || '').trim(), no: (val('qRetroNo')[i] || '').trim() }, referencia: refs(val('qRef')[i] || '')[0] || '' }));
    return { titulo: form.elements.titulo.value.trim(), duracion: form.elements.duracion.value.trim(), resumen: form.elements.resumen.value.trim(), objetivos: lineas(form.elements.objetivos.value), recursos: form.elements.recursos.value.split(',').map(x => x.trim()).filter(Boolean), bibliografia: refs(form.elements.bibliografia.value), lecciones, quiz };
  }

  /* ================= DOCUMENTOS JURÍDICOS ================= */
  function documentosLegales(ctx) {
    if (ctx.params.id) return documentoLegalDetalle(ctx.params.id);
    const tipos = TH.api.documentosLegales.tipos; const nombre = (t) => TH.util.nombreCatalogo(cat.tiposDocumentoLegal, t);
    const base = TH.api.documentosLegales.baseRegistro();
    const estadoRegistro = !base ? TH.ui.alerta('alerta', 'Registro de organizaciones pendiente de habilitación', 'No hay una versión publicada del aviso de información y autorización ni de la política de tratamiento de datos. Valida (aprobación jurídica) y publica el aviso transitorio para habilitar el registro; las políticas definitivas pueden cargarse después.')
      : base.origen === 'politica' ? TH.ui.alerta('exito', 'Registro habilitado con la política definitiva', 'Las organizaciones y colaboradores autorizan el tratamiento conforme a la política de datos versión ' + esc(base.documento.version) + (TH.api.documentosLegales.publicado('condiciones-uso') ? ' y aceptan las condiciones de uso versión ' + esc(TH.api.documentosLegales.publicado('condiciones-uso').version) : '; las condiciones de uso aún no están publicadas, por lo que no se exige su aceptación') + '.')
      : base.origen === 'aviso' ? TH.ui.alerta('exito', 'Registro habilitado con el aviso transitorio', 'Las organizaciones y colaboradores autorizan el tratamiento conforme al aviso de información versión ' + esc(base.documento.version) + ' (publicado el ' + esc(TH.util.fecha(base.documento.publicacion.fecha)) + '). Cuando publiques la política definitiva, sustituirá al aviso: las personas registradas serán informadas y, si lo indicas al publicar, se les pedirá nueva autorización.')
      : TH.ui.alerta('alerta', 'Entorno de desarrollo: registro de prueba con el aviso preparado', 'El aviso versión ' + esc(base.documento.version) + ' no ha sido validado. En desarrollo permite registrar datos ficticios; para registros reales debe aprobarse (revisión jurídica) y publicarse, y antes hay que completar: ' + esc((base.documento.pendientes || []).join(' ')));
    return TH.ui.encabezado('Documentos jurídicos', 'Aviso transitorio de registro, condiciones de uso y política de tratamiento de datos: versiones, aprobación jurídica, publicación e historial de autorizaciones. El registro de organizaciones no depende de las políticas definitivas: requiere una base de información y autorización publicada.') + estadoRegistro +
      tipos.map(t => { const vs = TH.api.documentosLegales.listar().filter(d => d.tipo === t).sort((a, b) => (b.fecha > a.fecha ? 1 : -1)); const pub = TH.api.documentosLegales.publicado(t); const enCurso = vs.some(d => ['borrador', 'en-revision-juridica', 'aprobado'].includes(d.estado));
        return '<div class="card mb-4"><div class="card__encabezado"><div><h3 class="card__titulo">' + esc(nombre(t)) + (t === 'aviso-registro' ? ' <span class="badge badge--violeta badge--sin-punto">transitorio</span>' : '') + '</h3><p class="card__sub">' + (pub ? 'Vigente: versión ' + esc(pub.version) + ' (publicada el ' + esc(TH.util.fecha(pub.publicacion.fecha)) + ')' : 'Sin versión publicada') + '</p></div>' + (puede('documentos:editar') && !enCurso ? '<button type="button" class="btn btn--secundario btn--sm" data-action="fma-doc-nueva-version" data-tipo="' + t + '">' + ic('mas') + ' Nueva versión</button>' : '') + '</div>' +
          TH.ui.tabla([{ titulo: 'Versión', render: d => '<a href="#/fma/documentos-legales?id=' + d.id + '"><strong>' + esc(d.version) + '</strong></a><div class="texto-xs texto-2">' + esc(d.id) + '</div>' }, { titulo: 'Estado', render: d => TH.ui.badgeCatalogo(cat.estadosDocumentoLegal, d.estado) }, { titulo: 'Aprobación jurídica', render: d => d.aprobacion ? esc(d.aprobacion.por) + ' · ' + esc(TH.util.fecha(d.aprobacion.fecha)) : '<span class="texto-2">Pendiente</span>' }, { titulo: 'Publicación', render: d => d.publicacion ? esc(TH.util.fecha(d.publicacion.fecha)) + (d.publicacion.requiereNuevaAutorizacion ? '<div class="texto-xs">requiere nueva autorización</div>' : '') : '—' }, { titulo: 'Autorizaciones', clase: 'num', render: d => { const e = TH.api.documentosLegales.estadisticasAceptacion(d.id); return String(e.aceptaciones) + (d.estado === 'publicado' && e.pendientes ? ' <span class="texto-xs texto-2">(' + e.pendientes + ' pendientes)</span>' : ''); } }, { titulo: '', clase: 'acciones', render: d => '<a class="btn btn--terciario btn--sm" href="#/fma/documentos-legales?id=' + d.id + '">Abrir</a>' }], vs, { caption: nombre(t), vacioTitulo: 'Sin versiones', vacioTexto: 'Crea la primera versión.' }) + '</div>'; }).join('');
  }
  function documentoLegalDetalle(id) {
    const d = TH.api.documentosLegales.obtener(id);
    if (!d) return TH.ui.vacio('Documento no encontrado', '', '<a class="btn btn--primario" href="#/fma/documentos-legales">Volver</a>');
    const acciones = [];
    if (puede('documentos:editar') && ['borrador', 'en-revision-juridica'].includes(d.estado)) acciones.push('<button type="button" class="btn btn--secundario" data-action="fma-doc-editar" data-id="' + d.id + '">' + ic('editar') + ' Editar</button>');
    if (puede('documentos:editar') && d.estado === 'borrador') acciones.push('<button type="button" class="btn btn--secundario" data-action="fma-doc-revision" data-id="' + d.id + '">Enviar a revisión jurídica</button>');
    if (puede('documentos:aprobar') && ['en-revision-juridica', 'borrador'].includes(d.estado)) acciones.push('<button type="button" class="btn btn--primario" data-action="fma-doc-aprobar" data-id="' + d.id + '" data-resultado="aprobada">Registrar aprobación jurídica</button><button type="button" class="btn btn--secundario" data-action="fma-doc-aprobar" data-id="' + d.id + '" data-resultado="cambios-requeridos">Pedir cambios</button>');
    if (puede('documentos:publicar') && d.estado === 'aprobado') acciones.push('<button type="button" class="btn btn--primario" data-action="fma-doc-publicar" data-id="' + d.id + '">Publicar como versión vigente</button>');
    return TH.ui.migas([{ texto: 'Documentos jurídicos', ruta: '/fma/documentos-legales' }, { texto: d.titulo + ' · ' + d.version }]) +
      TH.ui.encabezado(d.titulo, TH.ui.badge('Versión ' + d.version, 'neutro') + ' ' + TH.ui.badgeCatalogo(cat.estadosDocumentoLegal, d.estado) + ' <span class="texto-xs texto-2">Identificador: ' + esc(d.id) + '</span>', acciones.join('')) +
      '<div class="grid grid-sidebar"><div><article class="card">' + (d.secciones || []).map(x => '<h3>' + esc(x.titulo) + '</h3>' + (x.cuerpo || []).map(t => '<p>' + esc(t) + '</p>').join('') + (x.lista && x.lista.length ? '<ul>' + x.lista.map(l => '<li>' + esc(l) + '</li>').join('') + '</ul>' : '')).join('') + '</article></div>' +
      '<aside>' + (d.pendientes && d.pendientes.length && d.estado !== 'publicado' ? TH.ui.alerta('alerta', 'Pendiente antes de publicar', '<ul class="mb-0">' + d.pendientes.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>') : '') + '<div class="card">' + TH.ui.dl([['Autor', d.autor], ['Fecha', TH.util.fecha(d.fecha)], ['Aprobación jurídica', d.aprobacion ? d.aprobacion.por + ' · ' + TH.util.fechaLarga(d.aprobacion.fecha) + (d.aprobacion.nota ? ' · ' + d.aprobacion.nota : '') : 'Pendiente'], ['Publicación', d.publicacion ? d.publicacion.por + ' · ' + TH.util.fecha(d.publicacion.fecha) + (d.publicacion.requiereNuevaAutorizacion ? ' · requiere nueva autorización' : '') + (d.publicacion.nota ? ' · ' + d.publicacion.nota : '') : '—'], ['Autorizaciones registradas', (function () { const e = TH.api.documentosLegales.estadisticasAceptacion(d.id); return e.aceptaciones + ' de ' + e.registradas + ' personas registradas' + (d.estado === 'publicado' && e.pendientes ? ' · ' + e.pendientes + ' pendientes de aceptar o conocer' : ''); })()]]) + '</div><div class="card mt-4"><h3 class="card__titulo" style="font-size:var(--th-t-md)">Historial</h3>' + TH.ui.historial((d.historial || []).map(h => ({ fecha: h.fecha, actor: h.actor, accion: h.accion }))) + '</div></aside></div>';
  }
  function formularioDocumento(d) {
    return '<form id="form-doc" data-form="fma-doc" data-id="' + d.id + '" novalidate>' + '<div class="form-fila">' + TH.ui.campo({ name: 'titulo', label: 'Título', required: true, valor: d.titulo }) + TH.ui.campo({ name: 'version', label: 'Identificador de versión', required: true, valor: d.version, ayuda: 'Ej.: 2026-11-v1. Se registra en cada consentimiento.' }) + '</div>' +
      '<fieldset><legend class="texto-sm">Secciones (un párrafo por línea; las líneas que empiezan con "- " forman una lista)</legend>' + (d.secciones || []).map((x, i) => '<div class="campo"><label class="campo__label" for="dsec-' + i + '">' + esc(x.titulo) + '</label><input type="hidden" name="secTitulo" value="' + esc(x.titulo) + '"><textarea class="textarea" id="dsec-' + i + '" name="secCuerpo" rows="4">' + esc((x.cuerpo || []).concat((x.lista || []).map(l => '- ' + l)).join('\n')) + '</textarea></div>').join('') + '</fieldset><div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>';
  }

  /* ================= SELLO: MANIFESTACIONES DE INTERÉS ================= */
  function sello(ctx) {
    const lista = TH.api.sello.intereses().filter(i => !ui.selEstado || i.estado === ui.selEstado);
    const det = ctx.params.id ? TH.api.sello.intereses().find(i => i.id === ctx.params.id) : null;
    return TH.ui.encabezado('Sello Turquesa · Manifestaciones de interés', 'Organizaciones que han manifestado interés en el Sello. La evaluación formal, sus criterios y dictámenes se gestionan fuera de esta interfaz.') +
      '<div class="grid grid-sidebar"><div><div class="filtros"><div class="campo"><label class="sr-only" for="se">Estado</label><select class="select" id="se" data-change="fma-sel-estado"><option value="">Todos los estados</option>' + cat.estadosInteres.map(e => '<option value="' + e.id + '" ' + (ui.selEstado === e.id ? 'selected' : '') + '>' + esc(e.nombre) + '</option>').join('') + '</select></div></div>' +
      TH.ui.tabla([{ titulo: 'Organización', render: i => { const o = TH.api.organizaciones.obtener(i.orgId); return '<a href="#/fma/sello?id=' + i.id + '"><strong>' + esc(o ? o.nombre : i.organizacion || '—') + '</strong></a><div class="texto-xs texto-2">' + esc(i.contacto) + ' · ' + esc(i.email) + '</div>'; } }, { titulo: 'Fecha', render: i => esc(TH.util.fecha(i.fecha)) }, { titulo: 'Estado', render: i => TH.ui.badgeCatalogo(cat.estadosInteres, i.estado) }, { titulo: '', clase: 'acciones', render: i => '<a class="btn btn--terciario btn--sm" href="#/fma/sello?id=' + i.id + '">Gestionar</a>' }], lista, { caption: 'Manifestaciones de interés', vacioTitulo: 'Sin manifestaciones', vacioTexto: 'Aún no hay manifestaciones de interés.' }) + '</div>' +
      '<aside>' + (det ? '<div class="card"><h3 class="card__titulo">' + esc((TH.api.organizaciones.obtener(det.orgId) || {}).nombre || det.organizacion || 'Manifestación') + '</h3>' + TH.ui.dl([['Estado', TH.util.nombreCatalogo(cat.estadosInteres, det.estado)], ['Fecha', TH.util.fecha(det.fecha)], ['Contacto', det.contacto + (det.cargo ? ' · ' + det.cargo : '')], ['Correo', det.email], ['Teléfono', det.telefono || '—'], ['Motivación', det.motivacion || '—']]) +
        (det.estado === 'pendiente-envio' ? TH.ui.alerta('alerta', 'Pendiente de envío', 'Esta manifestación se registró localmente y no ha llegado a la base de datos de la Fundación. Requiere el servicio de envío (API) para considerarse recibida.') : '') +
        '<form data-form="fma-sello-gestionar" data-id="' + det.id + '" novalidate>' + TH.ui.campo({ name: 'estado', label: 'Nuevo estado', tipo: 'select', opciones: cat.estadosInteres.filter(e => e.id !== 'pendiente-envio'), valor: det.estado === 'pendiente-envio' ? 'recibida' : det.estado }) + TH.ui.campo({ name: 'nota', label: 'Nota de gestión', tipo: 'textarea', rows: 2 }) + '<button type="submit" class="btn btn--primario">Registrar gestión</button></form>' +
        (det.gestion && det.gestion.length ? '<hr><h4 class="texto-sm">Gestión</h4>' + det.gestion.slice().reverse().map(g => '<p class="texto-xs mb-2">' + esc(TH.util.fecha(g.fecha)) + ' · ' + esc(g.actor) + ' · ' + esc(TH.util.nombreCatalogo(cat.estadosInteres, g.estado)) + (g.nota ? '<br>' + esc(g.nota) : '') + '</p>').join('') : '') + '</div>' : '<div class="card card--suave"><p class="texto-sm mb-0">Selecciona una manifestación para gestionarla.</p></div>') + '</aside></div>';
  }

  /* ================= REPORTES ================= */
  function reportesFMA() {
    const t = TH.api.reportes.tableroFMA(); const prom = TH.api.reportes.dimensionesPromedio(); const orgs = TH.api.organizaciones.listar();
    return '<div class="no-imprimir">' + TH.ui.encabezado('Reportes', 'Consolidado de la plataforma para la Fundación. Cifras agregadas; sin datos personales de colaboradores.', '<button type="button" class="btn btn--primario" data-action="imprimir">' + ic('imprimir') + ' Descargar PDF</button><button type="button" class="btn btn--secundario" data-action="fma-exportar-orgs">' + ic('descargar') + ' Organizaciones CSV</button>') + '</div>' +
      '<div class="reporte"><div class="reporte__portada card"><div class="seccion__eyebrow">Turquesa Hub · Reporte consolidado</div><h1 style="font-size:var(--th-t-2xl)">Fundación Milagro de Abril</h1><p class="texto-2">Generado el ' + esc(TH.util.fechaLarga(new Date().toISOString())) + '</p></div>' +
      '<section class="reporte__seccion card mt-4"><h2>1. Cobertura</h2><div class="grid grid-4">' + TH.ui.kpi('Organizaciones', String(t.organizaciones)) + TH.ui.kpi('Diagnósticos completados', String(t.diagnosticosTerminados)) + TH.ui.kpi('Planes', String(t.planes)) + TH.ui.kpi('Participantes', String(t.colaboradoresParticipantes)) + '</div><h3 class="mt-4">Por municipio</h3>' + TH.graficos.barras(t.porMunicipio, { max: Math.max(1, ...t.porMunicipio.map(x => x.valor)), sufijo: '' }) + '</section>' +
      '<section class="reporte__seccion card mt-4"><h2>2. Lectura promedio por dimensión</h2><p class="texto-sm texto-2">Promedio de valores orientativos declarados por las organizaciones con autodiagnóstico completo. No constituye medición validada.</p>' + TH.graficos.barras(prom.map(p => ({ etiqueta: p.dim.corto + ' (n=' + p.n + ')', valor: p.promedio }))) + '</section>' +
      '<section class="reporte__seccion card mt-4"><h2>3. Organizaciones</h2>' + TH.ui.tabla([{ titulo: 'Organización', campo: 'nombre' }, { titulo: 'Sector', campo: 'sector' }, { titulo: 'Municipio', campo: 'municipio' }, { titulo: 'Diagnóstico', render: o => { const r = TH.api.organizaciones.resumen(o.id); return r.diagnosticoEstado === 'completado' ? TH.api.diagnostico.calcular(r.diag).global + '%' : esc(r.diagnosticoEstado === 'en-curso' ? 'en curso' : '—'); } }, { titulo: 'Plan', render: o => { const r = TH.api.organizaciones.resumen(o.id); return r.plan ? r.planPct + '%' : '—'; } }, { titulo: 'Estado', render: o => TH.ui.badgeCatalogo(cat.estadosOrganizacion, o.estado) }], orgs, { caption: 'Organizaciones' }) + '</section></div>';
  }

  /* ================= USUARIOS Y PERMISOS ================= */
  function usuarios() {
    const internos = TH.api.usuarios.internos(); const perfiles = TH.api.usuarios.perfilesPermiso(); const gestiona = puede('usuarios:gestionar');
    return TH.ui.encabezado('Usuarios y permisos', 'Cuentas internas de la Fundación. Se crean únicamente desde aquí (nunca por registro público) y se activan por correo. Las organizaciones y colaboradores no pueden obtener permisos administrativos.', gestiona ? '<button type="button" class="btn btn--primario" data-action="fma-usuario-nuevo">' + ic('mas') + ' Nuevo usuario interno</button>' : '') +
      TH.ui.tabla([{ titulo: 'Usuario', render: u => '<strong>' + esc(u.nombre) + '</strong><div class="texto-xs texto-2">' + esc(u.email) + (u.cargo ? ' · ' + esc(u.cargo) : '') + '</div>' }, { titulo: 'Permisos', render: u => (u.permisos || []).includes('*') ? TH.ui.badge('Administración integral', 'violeta') : (u.permisos || []).map(p => TH.ui.badge(p, 'neutro')).join(' ') }, { titulo: 'Estado', render: u => TH.ui.badge(u.estado === 'activo' ? 'Activo' : u.estado === 'pendiente-activacion' ? 'Pendiente de activación' : u.estado || '—', u.estado === 'activo' ? 'exito' : 'alerta') }, { titulo: 'Creado', render: u => esc(TH.util.fecha(u.fechaCreacion)) }, { titulo: '', clase: 'acciones', render: u => gestiona && u.id !== TH.auth.usuario().id ? '<button type="button" class="btn btn--terciario btn--sm" data-action="fma-usuario-permisos" data-id="' + u.id + '">Permisos</button>' : '' }], internos, { caption: 'Usuarios internos' }) +
      '<div class="card mt-4"><h3 class="card__titulo">Perfiles de permiso</h3>' + TH.ui.tabla([{ titulo: 'Perfil', render: p => '<strong>' + esc(p.nombre) + '</strong>' }, { titulo: 'Permisos', render: p => p.permisos.map(x => '<code>' + esc(x) + '</code>').join(' ') }], perfiles, { caption: 'Perfiles' }) + '<p class="texto-xs texto-2 mt-2">La revisión jurídica y la revisión psicológica/psicosocial son perfiles separados: solo la persona con el permiso correspondiente puede registrar esa revisión. El perfil de publicación no puede registrar revisiones.</p></div>';
  }

  /* ================= TRAZABILIDAD ================= */
  function auditoria() {
    const lista = TH.api.historial.listar({ entidad: ui.audEntidad }).filter(h => !ui.audQ || TH.util.buscar(h.accion + ' ' + nombreUsuario(h.actorId) + ' ' + (h.entidadId || ''), ui.audQ));
    const entidades = [...new Set(TH.api.historial.listar().map(h => h.entidad))].sort();
    return TH.ui.encabezado('Trazabilidad', 'Registro de acciones relevantes: registros, cambios de estado, revisiones, publicaciones, gestión de usuarios y configuración.', '<button type="button" class="btn btn--secundario" data-action="fma-exportar-auditoria">' + ic('descargar') + ' CSV</button>') +
      '<div class="filtros"><div class="buscador campo">' + ic('lupa') + '<label class="sr-only" for="aq">Buscar</label><input class="input" id="aq" type="search" placeholder="Acción, actor, identificador" value="' + esc(ui.audQ) + '" data-input="fma-aud-q"></div><div class="campo"><label class="sr-only" for="ae">Entidad</label><select class="select" id="ae" data-change="fma-aud-entidad"><option value="">Todas las entidades</option>' + entidades.map(e => '<option ' + (ui.audEntidad === e ? 'selected' : '') + '>' + esc(e) + '</option>').join('') + '</select></div></div>' +
      TH.ui.tabla([{ titulo: 'Fecha', render: h => esc(TH.util.fechaHora ? TH.util.fechaHora(h.fecha) : TH.util.fecha(h.fecha)) }, { titulo: 'Actor', render: h => esc(nombreUsuario(h.actorId)) }, { titulo: 'Acción', render: h => esc(h.accion) }, { titulo: 'Entidad', render: h => TH.ui.badge(h.entidad, 'neutro') + ' <span class="texto-xs texto-2">' + esc(h.entidadId || '') + '</span>' }, { titulo: 'Detalle', render: h => h.detalle ? '<span class="texto-xs">' + esc(typeof h.detalle === 'string' ? h.detalle : JSON.stringify(h.detalle)) + '</span>' : '' }], lista.slice(0, 300), { caption: 'Trazabilidad', vacioTitulo: 'Sin registros', vacioTexto: 'No hay registros para estos filtros.' });
  }

  /* ================= CONFIGURACIÓN ================= */
  function configuracionFMA() {
    const conf = TH.api.configuracion.obtener(); const u = TH.auth.usuario();
    return TH.ui.encabezado('Configuración', 'Parámetros de la plataforma y credenciales de tu cuenta.') +
      '<div class="grid grid-2"><form class="card" data-form="fma-config" novalidate><h3 class="card__titulo">Parámetros</h3>' + TH.ui.campo({ name: 'contactoSello', label: 'Correo de contacto para el Sello Turquesa', tipo: 'email', valor: conf.contactoSello || '' }) + TH.ui.campo({ name: 'diasInvitacion', label: 'Vigencia de invitaciones (días)', tipo: 'number', min: 1, max: 90, valor: conf.diasInvitacion || 30 }) + TH.ui.campo({ name: 'mensajeInicio', label: 'Mensaje de bienvenida para organizaciones (opcional)', tipo: 'textarea', rows: 2, valor: conf.mensajeInicio || '' }) + '<button type="submit" class="btn btn--primario" ' + (puede('*') ? '' : 'disabled') + '>Guardar</button></form>' +
      '<div><form class="card" data-form="cambiar-clave" novalidate><h3 class="card__titulo">Cambiar contraseña</h3>' + TH.ui.campo({ name: 'actual', label: 'Contraseña actual', tipo: 'password', required: true, attrs: ' autocomplete="current-password"' }) + TH.ui.campo({ name: 'nueva', label: 'Nueva contraseña', tipo: 'password', required: true, attrs: ' autocomplete="new-password"' }) + TH.ui.campo({ name: 'confirmacion', label: 'Confirmar nueva contraseña', tipo: 'password', required: true, attrs: ' autocomplete="new-password"' }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div><button type="submit" class="btn btn--primario">Actualizar contraseña</button></form>' +
      '<div class="card mt-4"><h3 class="card__titulo">Tu cuenta</h3>' + TH.ui.dl([['Nombre', u.nombre], ['Correo', u.email], ['Permisos', (u.permisos || []).join(', ')], ['Entorno', TH.config.entorno], ['Adaptador de autenticación', TH.config.auth.adaptador], ['Versión', TH.config.producto.version]]) + '</div></div></div>';
  }

  /* ================= MANEJADORES (asíncronos) ================= */
  function csv(filas) { return filas.map(f => f.map(v => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"').join(',')).join('\n'); }
  const refsValidas = (lista) => lista.filter(r => !TH.data.fuentes[r]);
  Object.assign(TH.acciones, {
    'fma-org-estado'(el) {
      const activar = el.dataset.estado === 'activa';
      TH.ui.modal({ titulo: activar ? 'Activar acceso' : 'Suspender acceso', cuerpo: '<form id="form-org-estado" data-form="fma-org-estado" data-id="' + esc(el.dataset.id) + '" data-estado="' + esc(el.dataset.estado) + '" novalidate><p class="texto-sm">' + (activar ? 'La organización y sus colaboradores recuperarán el acceso.' : 'La organización y sus colaboradores no podrán ingresar hasta que se reactive. Sus datos se conservan.') + '</p>' + TH.ui.campo({ name: 'motivo', label: 'Motivo', tipo: 'textarea', rows: 2, required: !activar }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-org-estado" class="btn ' + (activar ? 'btn--primario' : 'btn--peligro') + '">' + (activar ? 'Activar' : 'Suspender') + '</button>' });
    },
    async 'fma-exportar-orgs'(el) { if (TH.config.esRemoto) { await TH.ui.ejecutar(el, () => TH.http.descargar('/admin/reportes/organizaciones.csv', 'organizaciones-' + TH.util.hoy() + '.csv'), { texto: 'Generando…' }); return; } const filas = [['Organización', 'Tipo id.', 'Identificación', 'Sector', 'Tamaño', 'Departamento', 'Municipio', 'Responsable', 'Correo', 'Registro', 'Estado', 'Diagnóstico', 'Plan %']].concat(TH.api.organizaciones.listar().map(o => { const r = TH.api.organizaciones.resumen(o.id); return [o.nombre, o.tipoIdentificacion, o.identificacion, o.sector, o.tamano, o.departamento, o.municipio, o.responsable, o.email, o.fechaRegistro, o.estado, r.diagnosticoEstado, r.plan ? r.planPct : '']; })); TH.ui.descargar('organizaciones-' + TH.util.hoy() + '.csv', csv(filas), 'text/csv;charset=utf-8'); },
    async 'fma-exportar-auditoria'(el) { if (TH.config.esRemoto) { await TH.ui.ejecutar(el, () => TH.http.descargar('/admin/auditoria.csv', 'trazabilidad-' + TH.util.hoy() + '.csv'), { texto: 'Generando…' }); return; } const filas = [['Fecha', 'Actor', 'Acción', 'Entidad', 'Id', 'Detalle']].concat(TH.api.historial.listar().map(h => [h.fecha, nombreUsuario(h.actorId), h.accion, h.entidad, h.entidadId, h.detalle ? JSON.stringify(h.detalle) : ''])); TH.ui.descargar('trazabilidad-' + TH.util.hoy() + '.csv', csv(filas), 'text/csv;charset=utf-8'); },
    async 'fma-instr-alcance'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.configuracion.cambiarAlcancePregunta(el.dataset.id, el.dataset.alcance), { exito: 'Alcance actualizado. Los autodiagnósticos completados conservan su resultado.', ms: 4000 }); if (r.ok) TH.router.refrescar(); },
    'fma-instr-version'() { TH.ui.modal({ titulo: 'Crear versión borrador del instrumento', cuerpo: '<form id="form-ver" data-form="fma-instr-version" novalidate>' + TH.ui.campo({ name: 'nota', label: 'Nota de la versión', tipo: 'textarea', rows: 2, required: true }) + '<p class="texto-xs texto-2">La versión borrador requiere revisión técnica, psicosocial y jurídica antes de pasar a vigente. Esta interfaz no cambia la versión vigente de forma automática.</p><div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-ver" class="btn btn--primario">Crear</button>' }); },
    'fma-cont-estado-filtro'(el) { ui.contEstado = el.dataset.estado; TH.router.refrescar(); },
    'fma-contenido-nuevo'() { TH.ui.modal({ titulo: 'Nuevo contenido', grande: true, cuerpo: formularioContenido(null), pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-contenido" class="btn btn--primario">Crear borrador</button>' }); },
    'fma-contenido-editar'(el) { const c = TH.api.contenidos.obtener(el.dataset.id); TH.ui.modal({ titulo: 'Editar contenido', grande: true, cuerpo: TH.ui.alerta('alerta', '', 'Al guardar se crea una nueva versión y el contenido vuelve a revisión técnica; las revisiones previas no se heredan.') + formularioContenido(c), pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-contenido" class="btn btn--primario">Guardar nueva versión</button>' }); },
    'fma-contenido-estado'(el) { TH.ui.modal({ titulo: 'Cambiar estado', cuerpo: '<form id="form-est" data-form="fma-contenido-estado" data-id="' + esc(el.dataset.id) + '" data-estado="' + esc(el.dataset.estado) + '" novalidate><p class="texto-sm">Nuevo estado: <strong>' + esc(TH.util.nombreCatalogo(cat.estadosContenido, el.dataset.estado)) + '</strong>.</p>' + TH.ui.campo({ name: 'nota', label: 'Nota (opcional)', tipo: 'textarea', rows: 2 }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-est" class="btn btn--primario">Confirmar</button>' }); },
    'fma-revision'(el) { TH.ui.modal({ titulo: 'Registrar revisión ' + el.dataset.tipo, cuerpo: '<form id="form-rev" data-form="fma-revision" data-id="' + esc(el.dataset.id) + '" data-tipo="' + esc(el.dataset.tipo) + '" data-resultado="' + esc(el.dataset.resultado) + '" novalidate><p class="texto-sm">Resultado: <strong>' + esc(TH.util.nombreCatalogo(cat.estadosRevision, el.dataset.resultado)) + '</strong>. Quedará registrado con tu nombre, fecha y versión del contenido.</p>' + TH.ui.campo({ name: 'observaciones', label: 'Observaciones', tipo: 'textarea', rows: 3, required: el.dataset.resultado === 'cambios-requeridos' }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-rev" class="btn btn--primario">Registrar</button>' }); },
    /* Módulos formativos */
    async 'fma-modulo-nueva-version'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.modulos.crearVersion(el.dataset.modulo, ''), { texto: 'Creando…', exito: 'Nueva versión creada en borrador.' }); if (r.ok) TH.router.ir('/fma/formacion/version?id=' + r.modulo.id); },
    'fma-modulo-editar'(el) { const m = TH.api.modulos.obtenerVersion(el.dataset.id); if (!m) return; TH.ui.modal({ titulo: 'Editar módulo · v' + m.version, grande: true, cuerpo: TH.ui.alerta('alerta', '', 'Al guardar, las revisiones registradas sobre esta versión se reinician y la versión vuelve a borrador.') + formularioModulo(m), pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-modulo" class="btn btn--primario">Guardar cambios</button>' }); },
    'fma-modulo-estado'(el) { TH.ui.modal({ titulo: 'Cambiar estado del módulo', cuerpo: '<form id="form-mest" data-form="fma-modulo-estado" data-id="' + esc(el.dataset.id) + '" data-estado="' + esc(el.dataset.estado) + '" novalidate><p class="texto-sm">Nuevo estado: <strong>' + esc(TH.util.nombreCatalogo(cat.estadosModulo, el.dataset.estado)) + '</strong>.' + (el.dataset.estado === 'publicado' ? ' La versión publicada anterior (si existe) quedará archivada y los colaboradores verán esta versión.' : el.dataset.estado === 'retirado' ? ' El módulo dejará de estar disponible; el progreso ya registrado se conserva.' : '') + '</p>' + TH.ui.campo({ name: 'nota', label: 'Nota (opcional)', tipo: 'textarea', rows: 2 }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-mest" class="btn btn--primario">Confirmar</button>' }); },
    'fma-modulo-revision'(el) { TH.ui.modal({ titulo: 'Registrar revisión ' + el.dataset.tipo + ' del módulo', cuerpo: '<form id="form-mrev" data-form="fma-modulo-revision" data-id="' + esc(el.dataset.id) + '" data-tipo="' + esc(el.dataset.tipo) + '" data-resultado="' + esc(el.dataset.resultado) + '" novalidate><p class="texto-sm">Resultado: <strong>' + esc(TH.util.nombreCatalogo(cat.estadosRevision, el.dataset.resultado)) + '</strong>. Quedará registrado con tu nombre, fecha y versión.</p>' + TH.ui.campo({ name: 'observaciones', label: 'Observaciones', tipo: 'textarea', rows: 3, required: el.dataset.resultado === 'cambios-requeridos' }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-mrev" class="btn btn--primario">Registrar</button>' }); },
    /* Documentos jurídicos */
    async 'fma-doc-nueva-version'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.documentosLegales.crearVersion(el.dataset.tipo, {}), { texto: 'Creando…', exito: 'Versión creada en borrador.' }); if (r.ok) TH.router.ir('/fma/documentos-legales?id=' + r.documento.id); },
    'fma-doc-editar'(el) { const d = TH.api.documentosLegales.obtener(el.dataset.id); if (!d) return; TH.ui.modal({ titulo: 'Editar · ' + d.titulo, grande: true, cuerpo: formularioDocumento(d), pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-doc" class="btn btn--primario">Guardar</button>' }); },
    async 'fma-doc-revision'(el) { const r = await TH.ui.ejecutar(el, () => TH.api.documentosLegales.enviarARevision(el.dataset.id), { exito: 'Enviado a revisión jurídica.' }); if (r.ok) TH.router.refrescar(); },
    'fma-doc-aprobar'(el) { const ap = el.dataset.resultado === 'aprobada'; TH.ui.modal({ titulo: ap ? 'Registrar aprobación jurídica' : 'Pedir cambios', cuerpo: '<form id="form-dap" data-form="fma-doc-aprobar" data-id="' + esc(el.dataset.id) + '" data-resultado="' + esc(el.dataset.resultado) + '" novalidate><p class="texto-sm">' + (ap ? 'Declaras que revisaste este texto y lo apruebas jurídicamente. Quedará registrado con tu nombre, la fecha y el identificador de versión.' : 'La versión volverá a borrador para ajustes.') + '</p>' + TH.ui.campo({ name: 'nota', label: ap ? 'Nota (opcional)' : 'Cambios requeridos', tipo: 'textarea', rows: 3, required: !ap }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-dap" class="btn btn--primario">' + (ap ? 'Registrar aprobación' : 'Enviar') + '</button>' }); },
    'fma-doc-publicar'(el) {
      const d = TH.api.documentosLegales.obtener(el.dataset.id); if (!d) return;
      const transitorio = d.tipo === 'aviso-registro';
      TH.ui.modal({ titulo: 'Publicar versión vigente', cuerpo: '<form id="form-dpub" data-form="fma-doc-publicar" data-id="' + esc(d.id) + '" novalidate><p class="texto-sm">' + (transitorio ? 'El aviso transitorio pasará a ser la base de información y autorización del registro hasta que publiques la política de datos definitiva. Verifica que la información pendiente esté completa.' : 'Esta versión sustituye a la anterior (que queda archivada) y, si existe, al aviso transitorio. Las personas registradas serán informadas en la plataforma; las cuentas, diagnósticos y planes existentes no se modifican y no se registran aceptaciones retroactivas.') + '</p>' +
        (transitorio ? '' : TH.ui.check('requiereNuevaAutorizacion', 'Esta versión cambia las finalidades del tratamiento u otro aspecto que exige una <strong>nueva autorización</strong> de las personas registradas (se les pedirá aceptar expresamente). Si no se marca, solo se les informa.', false) + TH.ui.campo({ name: 'nota', label: 'Mensaje para las personas registradas (opcional)', tipo: 'textarea', rows: 2, ayuda: 'Ej.: qué cambia respecto a la versión anterior.' })) +
        '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-dpub" class="btn btn--primario">Publicar</button>' });
    },
    'fma-usuario-nuevo'() { TH.ui.modal({ titulo: 'Nuevo usuario interno', cuerpo: '<form id="form-usr" data-form="fma-usuario-nuevo" novalidate>' + TH.ui.campo({ name: 'nombre', label: 'Nombre', required: true }) + TH.ui.campo({ name: 'email', label: 'Correo institucional', tipo: 'email', required: true }) + TH.ui.campo({ name: 'cargo', label: 'Cargo o función' }) + TH.ui.campo({ name: 'perfil', label: 'Perfil de permisos', tipo: 'select', required: true, opciones: TH.api.usuarios.perfilesPermiso(), placeholder: 'Selecciona' }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div><p class="texto-xs texto-2">La persona recibirá un correo de activación para crear su contraseña. No se asigna contraseña inicial desde esta pantalla.</p></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-usr" class="btn btn--primario">Crear usuario</button>' }); },
    'fma-usuario-permisos'(el) { const u = TH.api.usuarios.obtener(el.dataset.id); const perfiles = TH.api.usuarios.perfilesPermiso(); const actual = perfiles.find(p => JSON.stringify(p.permisos) === JSON.stringify(u.permisos || [])); TH.ui.modal({ titulo: 'Permisos · ' + u.nombre, cuerpo: '<form id="form-perm" data-form="fma-usuario-permisos" data-id="' + u.id + '" novalidate>' + TH.ui.campo({ name: 'perfil', label: 'Perfil de permisos', tipo: 'select', required: true, opciones: perfiles, valor: actual ? actual.id : '', placeholder: 'Selecciona' }) + TH.ui.campo({ name: 'estado', label: 'Estado de la cuenta', tipo: 'select', opciones: [{ id: 'activo', nombre: 'Activo' }, { id: 'suspendido', nombre: 'Suspendido' }, { id: 'pendiente-activacion', nombre: 'Pendiente de activación' }], valor: u.estado || 'activo' }) + '<div class="campo" data-campo="general"><span class="campo__error" role="alert"></span></div></form>', pie: '<button type="button" class="btn btn--secundario" data-modal-cerrar>Cancelar</button><button type="submit" form="form-perm" class="btn btn--primario">Guardar</button>' }); }
  });
  Object.assign(TH.cambios, {
    'fma-org-estado'(el) { ui.orgEstado = el.value; TH.router.refrescar(); },
    'fma-org-sector'(el) { ui.orgSector = el.value; TH.router.refrescar(); },
    'fma-cont-cat'(el) { ui.contCat = el.value; TH.router.refrescar(); },
    'fma-sel-estado'(el) { ui.selEstado = el.value; TH.router.refrescar(); },
    'fma-aud-entidad'(el) { ui.audEntidad = el.value; TH.router.refrescar(); }
  });
  function refrescarConFoco(id, el) { const pos = el.selectionStart; TH.router.ir(TH.router.actual().ruta + '?sinScroll=1'); const n = document.getElementById(id); if (n) { n.focus(); try { n.setSelectionRange(pos, pos); } catch (_) { } } }
  Object.assign(TH.entradas, {
    'fma-org-q'(el) { ui.orgQ = el.value; refrescarConFoco('oq', el); },
    'fma-cont-q'(el) { ui.contQ = el.value; refrescarConFoco('cq', el); },
    'fma-aud-q'(el) { ui.audQ = el.value; refrescarConFoco('aq', el); }
  });
  const modalYRefrescar = async (form, fn, opciones) => { const r = await TH.ui.ejecutar(form, fn, opciones); if (!r.ok) return r; TH.ui.cerrarModal(); TH.router.refrescar(); return r; };
  Object.assign(TH.formularios, {
    async 'fma-org-estado'(form) { if (!TH.ui.validar(form)) return; await modalYRefrescar(form, () => TH.api.organizaciones.cambiarEstado(form.dataset.id, form.dataset.estado, form.elements.motivo.value.trim()), { exito: 'Estado de la organización actualizado.' }); },
    async 'fma-instr-version'(form) { if (!TH.ui.validar(form)) return; await modalYRefrescar(form, () => TH.api.configuracion.crearVersionInstrumento(form.elements.nota.value.trim()), { exito: 'Versión borrador creada.' }); },
    async 'fma-contenido'(form) {
      if (!TH.ui.validar(form)) return;
      const d = TH.ui.datosFormulario(form); d.secciones = leerSecciones(form); d.publico = [].concat(d.publico || []);
      const refs = (d.referencias || '').split(',').map(x => x.trim().toUpperCase()).filter(Boolean); const desconocidas = refsValidas(refs);
      if (desconocidas.length) { TH.ui.mostrarErrores(form, { referencias: 'Códigos no registrados en el registro de fuentes: ' + desconocidas.join(', ') + '. Añade la fuente al registro antes de citarla.' }); return; }
      d.referencias = refs; d.aplicaJuridica = !!d.aplicaJuridica; d.aplicaPsicosocial = !!d.aplicaPsicosocial; d.referencial = !!d.referencial;
      if (!d.publico.length) { TH.ui.mostrarErrores(form, { general: 'Selecciona al menos un público.' }); return; }
      const r = await TH.ui.ejecutar(form, () => form.dataset.id ? TH.api.contenidos.editar(form.dataset.id, d) : TH.api.contenidos.crear(d), { texto: 'Guardando…' });
      if (!r.ok) return;
      TH.ui.cerrarModal(); TH.ui.toast(form.dataset.id ? 'Nueva versión guardada; el contenido vuelve a revisión técnica.' : 'Borrador creado.', 'exito'); TH.router.ir('/fma/contenidos?id=' + (form.dataset.id || r.contenido.id));
    },
    async 'fma-contenido-estado'(form) { await modalYRefrescar(form, () => TH.api.contenidos.cambiarEstado(form.dataset.id, form.dataset.estado, form.elements.nota.value.trim()), { exito: 'Estado actualizado.' }); },
    async 'fma-revision'(form) { if (!TH.ui.validar(form)) return; await modalYRefrescar(form, () => TH.api.contenidos.registrarRevision(form.dataset.id, form.dataset.tipo, form.dataset.resultado, form.elements.observaciones.value), { exito: 'Revisión registrada.' }); },
    async 'fma-modulo'(form) {
      if (!TH.ui.validar(form)) return; const d = leerModulo(form);
      const desconocidas = refsValidas(d.bibliografia.concat(d.lecciones.flatMap(l => l.referencias)).concat(d.quiz.map(q => q.referencia).filter(Boolean)));
      if (desconocidas.length) { TH.ui.mostrarErrores(form, { bibliografia: 'Códigos no registrados en el registro de fuentes: ' + [...new Set(desconocidas)].join(', ') }); return; }
      await modalYRefrescar(form, () => TH.api.modulos.editar(form.dataset.id, d), { texto: 'Guardando…', exito: 'Módulo guardado; las revisiones se reinician.' });
    },
    async 'fma-modulo-estado'(form) { await modalYRefrescar(form, () => TH.api.modulos.cambiarEstado(form.dataset.id, form.dataset.estado, form.elements.nota.value.trim()), { exito: 'Estado actualizado.' }); },
    async 'fma-modulo-revision'(form) { if (!TH.ui.validar(form)) return; await modalYRefrescar(form, () => TH.api.modulos.registrarRevision(form.dataset.id, form.dataset.tipo, form.dataset.resultado, form.elements.observaciones.value), { exito: 'Revisión registrada.' }); },
    async 'fma-doc-publicar'(form) { await modalYRefrescar(form, () => TH.api.documentosLegales.publicar(form.dataset.id, { requiereNuevaAutorizacion: !!(form.elements.requiereNuevaAutorizacion && form.elements.requiereNuevaAutorizacion.checked), nota: form.elements.nota ? form.elements.nota.value : '' }), { exito: 'Versión publicada.' }); },
    async 'fma-doc'(form) { if (!TH.ui.validar(form)) return; await modalYRefrescar(form, () => TH.api.documentosLegales.editar(form.dataset.id, { titulo: form.elements.titulo.value.trim(), version: form.elements.version.value.trim(), secciones: leerSecciones(form) }), { texto: 'Guardando…', exito: 'Documento guardado (vuelve a borrador).' }); },
    async 'fma-doc-aprobar'(form) { if (!TH.ui.validar(form)) return; await modalYRefrescar(form, () => TH.api.documentosLegales.aprobar(form.dataset.id, form.dataset.resultado, form.elements.nota.value), { exito: form.dataset.resultado === 'aprobada' ? 'Aprobación jurídica registrada.' : 'Cambios solicitados.' }); },
    async 'fma-sello-gestionar'(form) { const r = await TH.ui.ejecutar(form, () => TH.api.sello.gestionarInteres(form.dataset.id, form.elements.estado.value, form.elements.nota.value), { exito: 'Gestión registrada.' }); if (r.ok) TH.router.refrescar(); },
    async 'fma-usuario-nuevo'(form) { if (!TH.ui.validar(form)) return; const d = TH.ui.datosFormulario(form); const perfil = TH.api.usuarios.perfilesPermiso().find(p => p.id === d.perfil); await modalYRefrescar(form, () => TH.api.usuarios.crearInterno({ nombre: d.nombre, email: d.email, cargo: d.cargo, permisos: perfil ? perfil.permisos : [] }), { texto: 'Creando…', exito: 'Usuario creado, pendiente de activación por correo.' }); },
    async 'fma-usuario-permisos'(form) { if (!TH.ui.validar(form)) return; if (!puede('usuarios:gestionar')) { TH.ui.toast('Sin permiso.', 'error'); return; } const perfil = TH.api.usuarios.perfilesPermiso().find(p => p.id === form.elements.perfil.value); await modalYRefrescar(form, () => TH.api.usuarios.actualizar(form.dataset.id, { permisos: perfil ? perfil.permisos : [], estado: form.elements.estado.value }), { exito: 'Permisos actualizados.' }); },
    async 'fma-config'(form) { if (!puede('*')) { TH.ui.toast('Sin permiso.', 'error'); return; } const d = TH.ui.datosFormulario(form); d.diasInvitacion = parseInt(d.diasInvitacion, 10) || 30; await TH.ui.ejecutar(form, () => TH.api.configuracion.guardar(d), { texto: 'Guardando…', exito: 'Configuración guardada.' }); }
  });

  TH.router.registrarVarias({
    '/fma/inicio': { roles: ROLES, titulo: 'Tablero general', render: inicio },
    '/fma/organizaciones': { roles: ROLES, permiso: 'organizaciones:ver', titulo: 'Organizaciones', render: organizaciones, ancho: true },
    '/fma/organizaciones/detalle': { roles: ROLES, permiso: 'organizaciones:ver', titulo: 'Organización', render: organizacionDetalle },
    '/fma/diagnosticos': { roles: ROLES, permiso: 'instrumento:ver', titulo: 'Instrumento y diagnósticos', render: diagnosticos, ancho: true },
    '/fma/planes': { roles: ROLES, permiso: 'organizaciones:ver', titulo: 'Planes de acción', render: planes },
    '/fma/contenidos': { roles: ROLES, permiso: 'contenidos:ver', titulo: 'Contenidos', render: contenidos, ancho: true },
    '/fma/formacion': { roles: ROLES, permiso: 'formacion:ver', titulo: 'Formación', render: formacionAdmin },
    '/fma/formacion/version': { roles: ROLES, permiso: 'formacion:ver', titulo: 'Módulo formativo', render: formacionVersion },
    '/fma/documentos-legales': { roles: ROLES, permiso: 'documentos:ver', titulo: 'Documentos jurídicos', render: documentosLegales },
    '/fma/sello': { roles: ROLES, permiso: 'organizaciones:ver', titulo: 'Manifestaciones de interés', render: sello },
    '/fma/reportes': { roles: ROLES, permiso: 'reportes:ver', titulo: 'Reportes', render: reportesFMA },
    '/fma/usuarios': { roles: ROLES, permiso: 'usuarios:gestionar', titulo: 'Usuarios y permisos', render: usuarios },
    '/fma/auditoria': { roles: ROLES, permiso: 'organizaciones:ver', titulo: 'Trazabilidad', render: auditoria, ancho: true },
    '/fma/configuracion': { roles: ROLES, titulo: 'Configuración', render: configuracionFMA }
  });
})();
